-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '3991,3992,3993,4006,4007,4008,4012,4014,4015,4016,4017,4020,4021,4030,4050,4051,4052,4056,4061,4066,4067,4070,4202,4409,5915,5916,5928,5930,5931,5932,7730,11910,11911,11912,11913,11914,34807,34894,34896,34897,34898,34911,34923,34931,34932,34933,34934,34937,34939,34940,34941,34946,34969,34982,35151,35154,35158,35160,35161,35174,35204,35333,35334,39254,40905,40906,41039,41062,41063,41071,41185,41230,41231,41291,41311,41367,41368,41369,41370,41407,41408,41432,41627,41673,41854,41864,41865,41870,41935,41937,41993,42026,42035,42039,42040,42047,42050,42125,51820,51825,51827,51828,51829,51830,51837';

